def comps_nonbg(g,bg,stoprow):
    R,C=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(stoprow):
      for c in range(C):
       if g[r][c]==bg or (r,c) in seen: continue
       st=[(r,c)]; seen.add((r,c)); comp=[]
       while st:
        x,y=st.pop(); comp.append((x,y,g[x][y]))
        for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
         if 0<=nx<stoprow and 0<=ny<C and (nx,ny) not in seen and g[nx][ny]!=bg:
          seen.add((nx,ny));st.append((nx,ny))
       comps.append(comp)
    return comps

def simulate(g, pid):
    out=[row[:] for row in g]
    cfg=configs[pid]
    stop=min(x[0] for x in cfg)
    # background mode upper region
    bg=collections.Counter(v for row in g[:stop] for v in row).most_common(1)[0][0]
    comps=comps_nonbg(g,bg,stop)
    for comp in comps:
      r0=min(x for x,y,v in comp); r1=max(x for x,y,v in comp)
      c0=min(y for x,y,v in comp); c1=max(y for x,y,v in comp)
      for r,c,v in comp: out[r][c]=bg
      for pr0,pr1,pc0,pc1,base,frame in cfg:
       if any(v==base for x,y,v in comp):
        dr=pr1-r1
        for r,c,v in comp:
         rr=r+dr
         if pr0<=rr<=pr1 and pc0<=c<=pc1:
          if v==base: out[rr][c]=frame
    return out, comps
